package net.officefloor.hq.app.claim;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OneToMany;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;

/**
 * A claim a person on a sheet makes: an amount (two decimals), a date, a note and a status (DRAFT
 * when added). A claim with a negative amount is a correction, naming the number of the SETTLED claim
 * of the same person it corrects.
 */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    /** The place the claim is listed at, newest first: given by the store when added, and again when moved by a merge. */
    @Column(name = "listed", insertable = false, updatable = false)
    private Long listed;

    /**
     * The claim's place in the order claims are added: given by the store when added to a sheet, and
     * again when transferred to another; null until stored (newer than every rate). A forward-only rate
     * applies only to claims added after it was saved.
     */
    @Column(name = "added_seq", insertable = false, updatable = false)
    private Long added;

    @Column(name = "amount", nullable = false, precision = 14, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    /**
     * The date the claim is due by: the terms-th business day after its due-from date (see
     * {@link BusinessDays#dueBy}), worked out again when a holiday on or before it is added unless it is SETTLED or VOID.
     */
    @Column(name = "due_by", nullable = false)
    private LocalDate dueBy;

    /** The terms, in business days, fixed when the claim was added: those in force on the sheet's today then, from its person's own terms, else their grade's. */
    @Column(name = "terms", nullable = false)
    private int terms;

    /** The date the claim's terms count from: its date when it was added (a later change of date keeps it). */
    @Column(name = "due_from", nullable = false)
    private LocalDate dueFrom;

    @Column(name = "note", nullable = false)
    private String note;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /** The sheet's number given to the claim when opened; null while DRAFT, and kept once VOID. */
    @Column(name = "claim_number")
    private String number;

    /** The due fixed when the claim was settled; null otherwise, or when the grade had no rate then. */
    @Column(name = "settled_due", precision = 14, scale = 2)
    private BigDecimal settledDue;

    /** The user who opened the claim; null until it is opened. */
    @Column(name = "opened_by")
    private String openedBy;

    /** The user who last edited the claim; null when it was never edited. */
    @Column(name = "edited_by")
    private String editedBy;

    /** The number of the bulk settle batch that settled the claim; null when not settled by one. */
    @Column(name = "settle_batch")
    private Integer settleBatch;


    /** Whether the claim is bound by its person's last statement. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The due figure the claim was bound to by the statement; null when unbound, or when it was n/a. */
    @Column(name = "stated_due", precision = 14, scale = 2)
    private BigDecimal statedDue;

    /**
     * Whether the bound figure is the claim's whole due as shown, late charge and floor included;
     * false for a figure bound before statements bound the late charge (the rate figure alone).
     */
    @Column(name = "stated_whole", nullable = false)
    private boolean statedWhole;

    /** The number of the claim this one corrects; null unless it is a correction. */
    @Column(name = "corrects")
    private String corrects;

    /** The claim's external reference; null when it has none. */
    @Column(name = "ref")
    private String ref;

    /** The reference as compared on the sheet (lower case); null when it has none. */
    @Column(name = "ref_key")
    private String refKey;

    /** The claim's tags, sorted and comma separated; null when it has none. */
    @Column(name = "tags")
    private String tags;

    /** Every tag the claim has ever carried, sorted and comma separated; null when none. */
    @Column(name = "tags_used")
    private String tagsUsed;

    /** The date the claim is deferred until; null when it was never deferred. */
    @Column(name = "deferred_until")
    private LocalDate deferredUntil;

    /** Whether a steward waived the claim's late charge; false when added. */
    @Column(name = "waived", nullable = false)
    private boolean waived;

    /** Whether the claim is held: held, it still counts in every total, and only marks the claim; false when added. */
    @Column(name = "held", nullable = false)
    private boolean held;

    /** The number of the claim this one was split from; null unless it was split off another. */
    @Column(name = "split_from")
    private String splitFrom;

    /** How many proofs the claim has; 0 when added. */
    @Column(name = "proofs", nullable = false)
    private int proofs;

    /** How many of the claim's proofs are receipts. */
    @Column(name = "proofs_receipt", nullable = false)
    private int proofsReceipt;

    /** How many of the claim's proofs are photos. */
    @Column(name = "proofs_photo", nullable = false)
    private int proofsPhoto;

    /** The last day (the sheet's today) a reminder was written for the claim; null when never reminded. */
    @Column(name = "reminded_on")
    private LocalDate remindedOn;

    /** Whether a reminder ever escalated the claim; a claim escalates once at most. */
    @Column(name = "escalated", nullable = false)
    private boolean escalated;

    /** The user whose open editor locks the claim for everyone else; null when no editor holds it. */
    @Column(name = "locked_by")
    private String lockedBy;

    /** Whether the claim was added while a period its date or due-by is in was soft-closed. */
    @Column(name = "late_entry", nullable = false)
    private boolean lateEntry;

    /** The reason from the sheet's list the claim was voided with; null when not voided with one. */
    @Column(name = "void_reason")
    private String voidReason;

    /** The claim's status log, oldest first. */
    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    @JoinColumn(name = "claim_id", nullable = false)
    @OrderBy("id")
    private List<ClaimLogLine> log = new ArrayList<>();

    /** The claim's comments, oldest first. */
    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    @JoinColumn(name = "claim_id", nullable = false)
    @OrderBy("id")
    private List<ClaimComment> comments = new ArrayList<>();

    /** The claim's lines, in the order they were added. */
    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    @JoinColumn(name = "claim_id", nullable = false)
    @OrderBy("id")
    private List<ClaimLine> lines = new ArrayList<>();

    protected Claim() {
    }

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, int terms, LocalDate dueBy,
            String note, String corrects) {
        this.terms = terms;
        this.dueFrom = date;
        this.dueBy = dueBy;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.corrects = corrects;
    }

    public Long getId() {
        return id;
    }

    /** The claim's place in the order claims are added; null until stored. */
    public Long getAdded() {
        return added;
    }

    /** Hold the place in the order claims are added kept for the claim, for a claim held in no store. */
    public void keepAdded(Long added) {
        this.added = added;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public LocalDate getDueBy() {
        return dueBy;
    }

    public int getTerms() {
        return terms;
    }

    public LocalDate getDueFrom() {
        return dueFrom;
    }

    /** Work the claim's due-by out again against the sheet's holidays now; its terms and due-from are kept. */
    public void workOutDueBy(Set<LocalDate> holidays) {
        this.dueBy = BusinessDays.dueBy(dueFrom, terms, holidays);
    }

    public String getNote() {
        return note;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public String getNumber() {
        return number;
    }

    public BigDecimal getSettledDue() {
        return settledDue;
    }

    public String getOpenedBy() {
        return openedBy;
    }

    /** Record the user who opened the claim. */
    public void openedBy(String user) {
        this.openedBy = user;
    }

    public String getEditedBy() {
        return editedBy;
    }

    /** Record the user who last edited the claim. */
    public void editedBy(String user) {
        this.editedBy = user;
    }

    public Integer getSettleBatch() {
        return settleBatch;
    }

    /** Record the bulk settle batch that settled the claim. */
    public void settledInBatch(int batch) {
        this.settleBatch = batch;
    }

    /** Whether the user opened or last edited the claim, and so cannot settle or approve it. */
    public boolean isOpenedOrEditedBy(String user) {
        return user.equals(openedBy) || user.equals(editedBy);
    }

    /** Fix the claim's due as it is settled. */
    public void settleDue(BigDecimal due) {
        this.settledDue = due;
    }

    /** Move the claim to a new status; the caller checks the move is allowed. */
    public void become(ClaimStatus status) {
        this.status = status;
    }

    public String getVoidReason() {
        return voidReason;
    }

    /** Record the reason the claim is voided with; null for none. */
    public void voidedWith(String reason) {
        this.voidReason = reason;
    }

    /** Give the claim its number when it is opened; it keeps it from then on. */
    public void number(String number) {
        this.number = number;
    }

    public String getCorrects() {
        return corrects;
    }

    public String getRef() {
        return ref;
    }

    /** Give the claim an external reference; null for none. */
    public void refer(String ref) {
        this.ref = ref;
        this.refKey = keyOf(ref);
    }

    /** The claim's tags, sorted; empty when it has none. */
    public java.util.List<String> getTags() {
        return tags == null ? java.util.List.of() : java.util.List.of(tags.split(","));
    }

    /** Give the claim its tags (see {@link #tagsOf}); empty for none. */
    public void tag(java.util.List<String> tags) {
        this.tags = tags.isEmpty() ? null : String.join(",", tags);
        java.util.List<String> used = java.util.stream.Stream.concat(getTagsUsed().stream(), tags.stream())
                .distinct().sorted().toList();
        this.tagsUsed = used.isEmpty() ? null : String.join(",", used);
    }

    /** Every tag the claim has ever carried, sorted; empty when none. */
    public java.util.List<String> getTagsUsed() {
        return tagsUsed == null ? java.util.List.of() : java.util.List.of(tagsUsed.split(","));
    }

    /**
     * Tags as a comma separated text gives them: each trimmed and lower case, blanks and repeats
     * dropped, sorted.
     */
    public static java.util.List<String> tagsOf(String text) {
        if (text == null) {
            return java.util.List.of();
        }
        return java.util.Arrays.stream(text.split(","))
                .map((t) -> t.trim().toLowerCase(java.util.Locale.ROOT))
                .filter((t) -> !t.isEmpty())
                .distinct()
                .sorted()
                .toList();
    }

    /** A reference as compared on a sheet, without regard to case; null for none. */
    public static String keyOf(String ref) {
        return ref == null ? null : ref.toLowerCase(java.util.Locale.ROOT);
    }

    /** Whether the claim is a correction: its amount is below 0.00. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }

    /** Change the claim's amount, date, note and the number it corrects. */
    public void change(BigDecimal amount, LocalDate date, String note, String corrects) {
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.corrects = corrects;
    }

    public boolean isStated() {
        return stated;
    }

    public BigDecimal getStatedDue() {
        return statedDue;
    }

    public boolean isStatedWhole() {
        return statedWhole;
    }

    /** Bind the claim to its due as shown, late charge and floor included (null when n/a), as a statement is taken. */
    public void bind(BigDecimal due) {
        bind(due, true);
    }

    /** Bind the claim to a figure (null when n/a): its whole due as shown, or its rate figure alone. */
    public void bind(BigDecimal due, boolean whole) {
        this.stated = true;
        this.statedDue = due;
        this.statedWhole = whole;
    }

    /** Move the claim to a new date; its due-by, number and any bound figure are kept. */
    public void redate(LocalDate date) {
        this.date = date;
    }

    /** Move the claim to another person on the sheet. */
    public void reassign(Long personId) {
        this.personId = personId;
    }

    /**
     * Move the claim with its person to another sheet: its status, dates, note, fixed figures, log
     * and any figure a statement bound are kept; it loses its reference, its settle batch and any
     * editor's lock. The caller gives it the other sheet's number.
     */
    public void transferTo(String sheetId) {
        this.sheetId = sheetId;
        refer(null);
        this.settleBatch = null;
        this.lockedBy = null;
    }

    /** Name other numbers for the claims this one corrects and was split from, as the map gives them. */
    public void renumberLinks(java.util.Map<String, String> numbers) {
        if (corrects != null) {
            this.corrects = numbers.getOrDefault(corrects, corrects);
        }
        if (splitFrom != null) {
            this.splitFrom = numbers.getOrDefault(splitFrom, splitFrom);
        }
    }

    /** The day the claim was first opened, as its status log records it; null when the log has none. */
    public LocalDate openedOn() {
        for (ClaimLogLine line : log) {
            if (line.getStatus() == ClaimStatus.OPEN) {
                return line.getOn();
            }
        }
        return null;
    }

    /** Leave the claim unbound, its due live again. */
    public void unbind() {
        this.stated = false;
        this.statedDue = null;
        this.statedWhole = false;
    }

    public LocalDate getDeferredUntil() {
        return deferredUntil;
    }

    /** Defer the claim until a date; the caller checks the deferral is allowed. */
    public void defer(LocalDate until) {
        this.deferredUntil = until;
    }

    /**
     * Whether the claim is deferred on a date (the sheet's today): it is OPEN and the date has not yet
     * reached the date it is deferred until.
     */
    public boolean isDeferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && today.isBefore(deferredUntil);
    }

    public boolean isWaived() {
        return waived;
    }

    /** Waive the claim's late charge; the caller checks the waiver is allowed. */
    public void waive() {
        this.waived = true;
    }

    public boolean isHeld() {
        return held;
    }

    /** Hold or release the claim; the caller checks the claim may be. */
    public void hold(boolean held) {
        this.held = held;
    }

    public String getSplitFrom() {
        return splitFrom;
    }

    /**
     * Split an amount off the claim: it keeps the rest of its amount and loses any figure a statement
     * bound it to. The new claim, OPEN with the split-off amount, the same date and note, names this
     * claim's number as the one it was split from; the caller numbers it and records who opened it.
     */
    public Claim split(BigDecimal off, int newTerms, LocalDate newDueBy) {
        Claim split = new Claim(sheetId, personId, off, date, newTerms, newDueBy, note, null);
        split.status = ClaimStatus.OPEN;
        split.splitFrom = number;
        this.amount = amount.subtract(off);
        unbind();
        return split;
    }

    public int getProofs() {
        return proofs;
    }

    /** How many of the claim's proofs are of a kind (receipt or photo). */
    public int getProofs(String kind) {
        return switch (kind) {
            case "receipt" -> proofsReceipt;
            case "photo" -> proofsPhoto;
            default -> throw new IllegalArgumentException("No such proof kind: " + kind);
        };
    }

    /** Raise the claim's proofs count, and its count of the kind (receipt or photo), by one; the caller checks the claim can take a proof. */
    public void addProof(String kind) {
        switch (kind) {
            case "receipt" -> proofsReceipt++;
            case "photo" -> proofsPhoto++;
            default -> throw new IllegalArgumentException("No such proof kind: " + kind);
        }
        proofs++;
    }

    public LocalDate getRemindedOn() {
        return remindedOn;
    }

    /** Mark the claim reminded on a day; the caller checks the claim can be reminded. */
    public void remind(LocalDate on) {
        this.remindedOn = on;
    }

    public boolean isEscalated() {
        return escalated;
    }

    /** Mark the claim escalated; the caller checks it was not already. */
    public void escalate() {
        this.escalated = true;
    }

    public String getLockedBy() {
        return lockedBy;
    }

    /** Whether the claim was added while a period its date or due-by is in was soft-closed. */
    public boolean isLateEntry() {
        return lateEntry;
    }

    /** Mark the claim as added while its period was soft-closed. */
    public void markLateEntry() {
        this.lateEntry = true;
    }

    /** Whether an editor of a user other than this one holds the claim. */
    public boolean isLockedAgainst(String user) {
        return lockedBy != null && !lockedBy.equals(user);
    }

    /** Lock the claim for the user's editor (null: release it); the caller checks the lock is theirs to take. */
    public void lockFor(String user) {
        this.lockedBy = user;
    }

    public List<ClaimComment> getComments() {
        return List.copyOf(comments);
    }

    public List<ClaimLine> getLines() {
        return List.copyOf(lines);
    }

    /** Add a line to the claim: its amount becomes the totals of its lines added up. */
    public void addLine(String label, int qty, BigDecimal unit) {
        lines.add(new ClaimLine(label, qty, unit));
        this.amount = lines.stream().map(ClaimLine::total).reduce(BigDecimal.ZERO, BigDecimal::add)
                .setScale(2);
    }

    /** Add a comment to the claim, by the user on the sheet's today. */
    public void comment(String by, LocalDate on, String text) {
        comments.add(new ClaimComment(by, on, text));
    }

    public List<ClaimLogLine> getLog() {
        return List.copyOf(log);
    }

    /**
     * The status the claim had at the end of a day, as its status log records it: the last line dated
     * on or before it, or null when the claim was added after it. A claim with no log (added before
     * the log) has its current status.
     */
    public ClaimStatus statusAt(LocalDate day) {
        if (log.isEmpty()) {
            return status;
        }
        ClaimStatus then = null;
        for (ClaimLogLine line : log) {
            if (!line.getOn().isAfter(day)) {
                then = line.getStatus();
            }
        }
        return then;
    }

    /**
     * The day the claim was last settled, as its status log records it: the date of its last SETTLED
     * line, or null when the log has none.
     */
    public LocalDate settledOn() {
        LocalDate on = null;
        for (ClaimLogLine line : log) {
            if (line.getStatus() == ClaimStatus.SETTLED) {
                on = line.getOn();
            }
        }
        return on;
    }

    /**
     * The day the claim was last deleted, as its status log records it: the date of its last DELETED
     * line, or null when the log has none.
     */
    public LocalDate deletedOn() {
        LocalDate on = null;
        for (ClaimLogLine line : log) {
            if (line.getStatus() == ClaimStatus.DELETED) {
                on = line.getOn();
            }
        }
        return on;
    }

    /** Add a line to the claim's status log for the status it now has. */
    public void logged(String by, LocalDate on, BigDecimal due) {
        log.add(new ClaimLogLine(status, by, on, due));
    }
}

package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.history.SheetHistory;
import net.officefloor.hq.app.holiday.HolidayService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.Retirement;
import net.officefloor.hq.app.period.PeriodService;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.WatchService;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.sheet.TodayChanged;
import net.officefloor.hq.app.voidreason.VoidReasonService;
import org.springframework.context.event.EventListener;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The claims people on a sheet make: listed, added, edited and moved through their statuses. */
@Service
public class ClaimService {

    /** Shown in place of a due when the grade has no rate. */
    private static final String NO_RATE = "n/a";

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final Dues dues;
    private final SheetService sheets;
    private final Rollups rollups;
    private final PeriodService periods;
    private final RoleService roles;
    private final WatchService watches;
    private final HolidayService holidays;
    private final VoidReasonService voidReasons;
    private final SheetHistory history;
    private final Audit audit;

    public ClaimService(ClaimRepository claims, PersonRepository people, Dues dues, SheetService sheets,
            Rollups rollups, PeriodService periods, RoleService roles, WatchService watches, HolidayService holidays,
            VoidReasonService voidReasons, SheetHistory history, Audit audit) {
        this.history = history;
        this.watches = watches;
        this.holidays = holidays;
        this.voidReasons = voidReasons;
        this.periods = periods;
        this.roles = roles;
        this.claims = claims;
        this.people = people;
        this.dues = dues;
        this.sheets = sheets;
        this.rollups = rollups;
        this.audit = audit;
    }

    /** A settle batch: its number, and the claims it settled, as they are now, in the order given. */
    public record Batch(int number, List<Claim> claims) {
    }

    /**
     * Make the claims a bulk settle settled the sheet's next settle batch: each carries its number.
     * Audited as BATCH_SETTLED with the batch number, how many claims it holds, and the frozen figures
     * of those of them SETTLED, added up.
     */
    @Transactional
    public Batch batch(String sheetId, String user, List<Long> claimIds) {
        int number = sheets.lock(sheetId).nextSettleBatch();
        List<Claim> batched = new ArrayList<>();
        BigDecimal total = BigDecimal.ZERO;
        for (Long id : claimIds) {
            Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow();
            claim.settledInBatch(number);
            if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
                total = total.add(claim.getSettledDue());
            }
            batched.add(claims.save(claim));
        }
        audit.recordOnCommit("BATCH_SETTLED sheet=" + sheetId + " by=" + user + " batch=" + number
                + " count=" + batched.size() + " total=" + total.setScale(2, RoundingMode.HALF_UP).toPlainString());
        return new Batch(number, batched);
    }

    /** The sheet's claims, newest first. */
    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
    }

    /**
     * The sheet's duplicate claims: for each person, date and amount with two or more claims (VOID and
     * DELETED claims left out), one line {@code <name> <date> <amount> x<count>}; people in list order,
     * then by date, then by amount.
     */
    @Transactional(readOnly = true)
    public List<String> duplicates(String sheetId) {
        Map<Long, Map<LocalDate, Map<BigDecimal, Integer>>> counts = new HashMap<>();
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            if (claim.getStatus() == ClaimStatus.VOID || claim.getStatus() == ClaimStatus.DELETED) {
                continue;
            }
            counts.computeIfAbsent(claim.getPersonId(), id -> new TreeMap<>())
                    .computeIfAbsent(claim.getDate(), date -> new TreeMap<>())
                    .merge(claim.getAmount().setScale(2, RoundingMode.HALF_UP), 1, Integer::sum);
        }
        List<String> lines = new ArrayList<>();
        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
            counts.getOrDefault(person.getId(), Map.of()).forEach((date, amounts) -> amounts.forEach((amount, count) -> {
                if (count >= 2) {
                    lines.add(person.getName() + " " + date + " " + amount.toPlainString() + " x" + count);
                }
            }));
        }
        return lines;
    }

    /**
     * Add a claim for a person on the sheet; with no date it is dated the sheet's entry date
     * while one is set, else the sheet's today. One given a date in a soft-closed period (with no date given, the
     * sheet's today in one), or due by in one, is a late entry, audited as LATE_ENTRY after its CLAIM_ADDED. A DRAFT may be added
     * due by inside a closed period (it cannot be opened or changed there). Refused when it is a correction that does not name a SETTLED claim
     * of the same person (see {@link #refuseUnlessCorrects}).
     */
    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        return add(sheetId, user, personId, amount, date, note, corrects, null);
    }

    /**
     * Add a claim (see {@link #add(String, String, long, BigDecimal, LocalDate, String, String)}) with an
     * external reference (blank: none); refused when the reference is already used on the sheet, comparing
     * without regard to case. CLAIM_ADDED ends with ref=&lt;reference&gt; when one was given.
     */
    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref) {
        return add(sheetId, user, personId, amount, date, note, corrects, ref, null);
    }

    /**
     * Add a claim (see {@link #add(String, String, long, BigDecimal, LocalDate, String, String, String)}) with
     * its tags, comma separated (see {@link Claim#tagsOf}). CLAIM_ADDED ends with tags=&lt;tags, sorted and
     * comma separated&gt; when any were given.
     */
    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref, String tags) {
        Rollups.Rollup before = rollups.take(sheetId);
        Person person = person(sheetId, personId);
        LocalDate dated = date != null ? date : sheets.load(sheetId).defaultClaimDate();
        Sheet sheet = sheets.lock(sheetId);
        int terms = terms(sheet, person, sheet.getToday());
        LocalDate dueBy = holidays.dueBy(sheetId, dated, terms);
        // Whether a new claim lands in a closed period is judged by its terms in calendar days from its date.
        periods.refuseIfClosed(sheetId, dated.plusDays(terms));
        refuseIfRetired(person, dated);
        refuseUnlessCorrects(sheetId, personId, amount, corrects, null);
        String referred = reference(ref);
        refuseIfReferred(sheetId, referred, null);
        Claim added = new Claim(sheetId, personId, money(amount), dated, terms, dueBy, clean(note), corrects);
        added.refer(referred);
        List<String> tagged = Claim.tagsOf(tags);
        added.tag(tagged);
        // A claim dated by the sheet's entry date is meant to be dated there: it is late by the sheet's today.
        LocalDate entered = date != null ? date : sheet.getToday();
        if (periods.softClosedOn(sheetId, entered) || periods.softClosedOn(sheetId, dueBy)) {
            added.markLateEntry();
        }
        Claim claim = claims.saveAndFlush(added);
        claim = logged(claim, user, person);
        audited("CLAIM_ADDED", sheetId, user, person, claim, claim.getNumber(),
                (referred != null ? " ref=" + referred : "")
                        + (tagged.isEmpty() ? "" : " tags=" + String.join(",", tagged)));
        if (claim.isLateEntry()) {
            audited("LATE_ENTRY", sheetId, user, person, claim);
        }
        rollups.audit(sheetId, user, before);
        return claim;
    }

    /**
     * Change a claim's amount, date, note and the number it corrects; with no date it keeps its own. Only a DRAFT claim can be
     * edited: an OPEN one is changed by voiding it and adding a new one. It keeps the due-by fixed when it
     * was added, and so its period. Refused when the claim's due-by, or a new date plus its terms in
     * calendar days, is inside a closed period, or when it
     * would be a correction that does not name a SETTLED claim of the same person, or when its external
     * reference (null: kept as it is; blank: none) is already used by another claim on the sheet. Its tags
     * (null: kept as they are) are set from the comma separated text (see {@link Claim#tagsOf}).
     */
    @Transactional
    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref, String tags) {
        Rollups.Rollup before = rollups.take(sheetId);
        sheets.lock(sheetId);
        Claim claim = claim(sheetId, claimId);
        refuseUnlessEditable(sheetId, user, claim);
        if (date != null) {
            refuseIfRetired(person(sheetId, claim.getPersonId()), date);
            if (!date.equals(claim.getDate())) {
                periods.refuseIfClosed(sheetId, date.plusDays(claim.getTerms()));
            }
        }
        if (!claim.getLines().isEmpty() && money(amount).compareTo(claim.getAmount()) != 0) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A claim with lines takes its amount from them: " + claim.getAmount().toPlainString() + ".");
        }
        refuseUnlessCorrects(sheetId, claim.getPersonId(), amount, corrects, claim.getId());
        String referred = ref == null ? claim.getRef() : reference(ref);
        refuseIfReferred(sheetId, referred, claim.getId());
        claim.refer(referred);
        if (tags != null) {
            claim.tag(Claim.tagsOf(tags));
        }
        claim.change(money(amount), date != null ? date : claim.getDate(), clean(note), corrects);
        claim.lockFor(null);
        claim.editedBy(user);
        Claim saved = claims.saveAndFlush(claim);
        audited("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved);
        rollups.audit(sheetId, user, before);
        return saved;
    }

    /**
     * Add a line to a DRAFT claim: a label, a quantity (at least 1) and a unit amount (two decimals); the
     * claim's amount becomes its lines' quantities times their unit amounts, added up. It counts as an
     * edit of the claim, refused as one is (see {@link #refuseUnlessEditable}), and is audited as
     * CLAIM_LINE_ADDED with the claim's new amount, ending label=&lt;label&gt; qty=&lt;qty&gt; unit=&lt;unit&gt;.
     */
    @Transactional
    public Claim addLine(String sheetId, String user, long claimId, String label, int qty, BigDecimal unit) {
        String trimmed = clean(label);
        if (trimmed.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A line needs a label.");
        }
        Rollups.Rollup before = rollups.take(sheetId);
        sheets.lock(sheetId);
        Claim claim = claim(sheetId, claimId);
        refuseUnlessEditable(sheetId, user, claim);
        BigDecimal unitAmount = money(unit);
        claim.addLine(trimmed, qty, unitAmount);
        claim.editedBy(user);
        Claim saved = claims.saveAndFlush(claim);
        audited("CLAIM_LINE_ADDED", sheetId, user, person(sheetId, saved.getPersonId()), saved, saved.getNumber(),
                " label=" + trimmed + " qty=" + qty + " unit=" + unitAmount.toPlainString());
        rollups.audit(sheetId, user, before);
        return saved;
    }

    /**
     * Open a claim's editor for the user: the claim is locked for every other user until the editor is
     * saved or cancelled, or the sheet's today changes. Refused, taking no lock, when the claim cannot
     * be edited (see {@link #edit}) or another user's editor holds it.
     */
    @Transactional
    public Claim lock(String sheetId, String user, long claimId) {
        sheets.lock(sheetId);
        Claim claim = claim(sheetId, claimId);
        refuseUnlessEditable(sheetId, user, claim);
        claim.lockFor(user);
        return claims.saveAndFlush(claim);
    }

    /** Cancel the user's editor of a claim, releasing its lock; a lock another user holds is left as it is. */
    @Transactional
    public Claim unlock(String sheetId, String user, long claimId) {
        sheets.lock(sheetId);
        Claim claim = claim(sheetId, claimId);
        if (user.equals(claim.getLockedBy())) {
            claim.lockFor(null);
            claim = claims.saveAndFlush(claim);
        }
        return claim;
    }

    /** The sheet's today was changed: every editor's lock on its claims is released. */
    @EventListener
    public void todayChanged(TodayChanged change) {
        claims.unlockAll(change.sheetId());
    }

    /**
     * Refuse an edit of a claim that is not a DRAFT, that is due by inside a closed period, or that
     * another user's editor holds (423).
     */
    private void refuseUnlessEditable(String sheetId, String user, Claim claim) {
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be edited; only a DRAFT can.");
        }
        periods.refuseIfClosed(sheetId, claim.getDueBy());
        if (claim.isLockedAgainst(user)) {
            throw new ResponseStatusException(HttpStatus.LOCKED,
                    "The claim is being edited by " + claim.getLockedBy() + ".");
        }
    }

    /**
     * Move a claim to a new status, recording the event; refused (and nothing written) when the
     * claim's current status does not allow the move. Settling fixes the claim's due at the rate
     * the person's grade has in force on the claim's date, or at the figure a statement bound it to,
     * with the late charge it has then frozen in.
     * Opening numbers the claim and records who opened it; a voided claim keeps its number, which
     * is never reused. The user who opened a claim,
     * or last edited it, is refused when settling it. A clerk settling a claim whose due is above the sheet's clerk limit
     * (a due of n/a is within any limit) sends it PENDING instead, for a steward to approve or reject;
     * a steward settles any. A move the sheet's permission matrix does not allow the user's role is
     * refused. A claim due by inside a closed period cannot be moved, nor can a claim
     * deferred on the sheet's today be settled, nor a claim opened by anyone but a steward whose person is
     * flagged on the sheet's today, nor a claim opened whose person already has as many OPEN
     * or PENDING claims due by in its period as the period's claim cap. A claim opened whose due is above the
     * sheet's review threshold in force on its date (a due of n/a is within any threshold) goes to REVIEW
     * instead, with no number yet, audited as CLAIM_REVIEW (see {@link #review}). A SETTLED claim is voided only by a steward, within
     * {@link ClaimStatus#VOID_SETTLED_DAYS} days of its settlement; its frozen figure leaves every
     * total and the audit records it as reversed.
     */
    @Transactional
    public Claim move(String sheetId, String user, long claimId, ClaimStatus next) {
        return move(sheetId, user, claimId, next, null);
    }

    /**
     * Move a claim as {@link #move(String, String, long, ClaimStatus)} does, voiding it with a reason:
     * while the sheet's list of void reasons is not empty, a void needs one from it (see
     * {@link VoidReasonService#require}); the claim keeps it and its audit record ends with it.
     */
    @Transactional
    public Claim move(String sheetId, String user, long claimId, ClaimStatus next, String reason) {
        return move(sheetId, user, claimId, next, reason, null);
    }

    /**
     * Settle a claim as {@link #move(String, String, long, ClaimStatus)} does, as of a date (null: the
     * sheet's today): its figure is frozen at the due it had at the end of that date, every change made
     * while the sheet's today was after it left out and that date standing in for the sheet's today, and
     * its audit record ends with the date. Refused for a date after the sheet's today, or one the claim
     * did not yet exist on.
     */
    @Transactional
    public Claim settle(String sheetId, String user, long claimId, LocalDate on) {
        return move(sheetId, user, claimId, ClaimStatus.SETTLED, null, on);
    }

    private Claim move(String sheetId, String user, long claimId, ClaimStatus next, String reason, LocalDate on) {
        // Every move takes the sheet's lock before reading the claim, so concurrent opens on the
        // sheet are serialised: each sees the other's committed claim and number.
        LocalDate today = sheets.lock(sheetId).getToday();
        Rollups.Rollup before = rollups.take(sheetId);
        Claim claim = claim(sheetId, claimId);
        periods.refuseIfClosed(sheetId, claim.getDueBy());
        String action = switch (next) {
            case OPEN -> "open";
            case SETTLED -> "settle";
            case VOID -> "void";
            case PENDING, DRAFT, DELETED, REVIEW -> throw new IllegalArgumentException("No move to " + next + ".");
        };
        if (!roles.permits(sheetId, user, action)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " a claim.");
        }
        if (!claim.getStatus().canBecome(next)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
        }
        boolean voidingSettled = next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
        if (voidingSettled) {
            refuseVoidingSettled(sheetId, user, claim, today);
        }
        String voidReason = next == ClaimStatus.VOID ? voidReasons.require(sheetId, reason) : null;
        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(today)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "The claim is deferred until " + claim.getDeferredUntil() + ": it cannot be settled before then.");
        }
        if (next == ClaimStatus.SETTLED && claim.isOpenedOrEditedBy(user)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "The user who opened or last edited a claim cannot settle it.");
        }
        Person person = person(sheetId, claim.getPersonId());
        BigDecimal settledDue = next == ClaimStatus.SETTLED
                ? settlingOn(sheetId, claim, person, today, on)
                : null;
        if (next == ClaimStatus.OPEN && person.flaggedOn(today)
                && !Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    person.getName() + " is flagged (" + person.getFlagReason() + "): only a steward opens their claims.");
        }
        if (next == ClaimStatus.OPEN) {
            periods.refuseIfCapped(sheetId, claim);
            BigDecimal due = dues.due(claim, person.gradeOn(claim.getDate()));
            refuseUnnoted(sheetId, claim, due);
            if (overReviewThreshold(sheetId, claim, due)) {
                next = ClaimStatus.REVIEW;
            }
        }
        if (next == ClaimStatus.SETTLED) {
            refuseUnproved(sheetId, claim, person.gradeOn(claim.getDate()), settledDue);
        }
        if (next == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, person.gradeOn(today), settledDue)) {
            next = ClaimStatus.PENDING;
            settledDue = null;
        }
        claim.become(next);
        if (next == ClaimStatus.OPEN) {
            claim.number(periods.nextClaimNumber(sheetId, claim.getDueBy()));
        }
        if (next == ClaimStatus.OPEN || next == ClaimStatus.REVIEW) {
            claim.openedBy(user);
        }
        if (next == ClaimStatus.SETTLED) {
            claim.settleDue(settledDue);
        }
        if (next == ClaimStatus.VOID) {
            claim.voidedWith(voidReason);
        }
        Claim saved = logged(claims.saveAndFlush(claim), user, person);
        String event = switch (next) {
            case OPEN -> "CLAIM_OPENED";
            case SETTLED -> "CLAIM_SETTLED";
            case PENDING -> "CLAIM_PENDING";
            case REVIEW -> "CLAIM_REVIEW";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT, DELETED -> throw new IllegalStateException();
        };
        String suffix = next == ClaimStatus.SETTLED
                ? " due=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE)
                : voidingSettled
                ? " reversed=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE)
                : "";
        if (voidReason != null) {
            suffix += " reason=" + voidReason;
        }
        if (next == ClaimStatus.SETTLED && on != null) {
            suffix += " on=" + on;
        }
        audited(event, sheetId, user, person, saved, saved.getNumber(), suffix);
        if (next == ClaimStatus.SETTLED) {
            watches.notifyWatchers(sheetId, user, person, saved.getNumber());
        }
        rollups.audit(sheetId, user, before);
        return saved;
    }

    /**
     * The due a claim is settled at as of a date (null: the sheet's today, as it stands): on the sheet's
     * today its live settling figure; before it, its due as the claim stood at the end of that date,
     * read against the sheet as kept then. Refused for a date after the sheet's today, or one the claim
     * (or its person) was not yet kept on.
     */
    private BigDecimal settlingOn(String sheetId, Claim claim, Person person, LocalDate today, LocalDate on) {
        if (on == null || on.equals(today)) {
            return dues.settling(claim, person.gradeOn(claim.getDate()));
        }
        if (today == null || on.isAfter(today)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                    "A claim cannot be settled as of a date after today.");
        }
        ResponseStatusException notYet = new ResponseStatusException(HttpStatus.BAD_REQUEST,
                "The claim did not exist on " + on + ": it cannot be settled as of then.");
        SheetHistory.AsOf kept = history.at(sheetId, on).orElseThrow(() -> notYet);
        Claim then = kept.claims().get(claim.getId());
        Person personThen = then == null ? null : kept.people().get(then.getPersonId());
        if (then == null || personThen == null) {
            throw notYet;
        }
        return dues.due(then, personThen.gradeOn(then.getDate()), kept.basis());
    }

    /**
     * Delete a DRAFT claim: it is DELETED, counts nowhere and cannot be edited, opened or voided, until
     * it is restored. Refused when the claim is not a DRAFT or is due by inside a closed period.
     */
    @Transactional
    public Claim delete(String sheetId, String user, long claimId) {
        sheets.lock(sheetId);
        Claim claim = claim(sheetId, claimId);
        periods.refuseIfClosed(sheetId, claim.getDueBy());
        if (!claim.getStatus().canBecome(ClaimStatus.DELETED)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be deleted; only a DRAFT can.");
        }
        claim.become(ClaimStatus.DELETED);
        claim.lockFor(null);
        Person person = person(sheetId, claim.getPersonId());
        Claim saved = logged(claims.saveAndFlush(claim), user, person);
        audited("CLAIM_DELETED", sheetId, user, person, saved);
        return saved;
    }

    /**
     * Restore a DELETED claim to a DRAFT; refused when the claim is not DELETED, when the sheet's today
     * is not the day it was deleted, or when it is due by inside a closed period.
     */
    @Transactional
    public Claim restore(String sheetId, String user, long claimId) {
        LocalDate today = sheets.lock(sheetId).getToday();
        Claim claim = claim(sheetId, claimId);
        periods.refuseIfClosed(sheetId, claim.getDueBy());
        if (!claim.getStatus().canBecome(ClaimStatus.DRAFT)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be restored; only a DELETED one can.");
        }
        if (today == null || !today.equals(claim.deletedOn())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A claim can only be restored on the day it was deleted, " + claim.deletedOn() + ".");
        }
        if (claim.isCorrection()) {
            refuseUnlessCorrects(sheetId, claim.getPersonId(), claim.getAmount(), claim.getCorrects(), claim.getId());
        }
        claim.become(ClaimStatus.DRAFT);
        Person person = person(sheetId, claim.getPersonId());
        Claim saved = logged(claims.saveAndFlush(claim), user, person);
        audited("CLAIM_RESTORED", sheetId, user, person, saved);
        return saved;
    }

    /**
     * Add a proof of a kind (null when none was chosen: a receipt) to a claim; refused when the claim is
     * SETTLED or VOID. The audit record carries the kind only when one was chosen.
     */
    @Transactional
    public Claim addProof(String sheetId, String user, long claimId, String kind) {
        sheets.lock(sheetId);
        Claim claim = claim(sheetId, claimId);
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot take a proof.");
        }
        claim.addProof(kind == null ? "receipt" : kind);
        Claim saved = claims.saveAndFlush(claim);
        audited("CLAIM_PROOF_ADDED", sheetId, user, person(sheetId, saved.getPersonId()), saved, saved.getNumber(),
                " proofs=" + saved.getProofs() + (kind == null ? "" : " kind=" + kind));
        return saved;
    }

    /**
     * Comment on a claim, in any status: the comment is kept with the user and the sheet's today, and
     * audited as COMMENT_ADDED ending text=&lt;text&gt;. Refused when the text is blank.
     */
    @Transactional
    public Claim comment(String sheetId, String user, long claimId, String text) {
        String trimmed = clean(text);
        if (trimmed.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A comment cannot be empty.");
        }
        LocalDate today = sheets.lock(sheetId).getToday();
        Claim claim = claim(sheetId, claimId);
        claim.comment(user, today, trimmed);
        Claim saved = claims.saveAndFlush(claim);
        audited("COMMENT_ADDED", sheetId, user, person(sheetId, saved.getPersonId()), saved, saved.getNumber(),
                " text=" + trimmed);
        return saved;
    }

    /**
     * Remind an OPEN or PENDING claim: the claim shows the sheet's today as its reminded date. Refused
     * when the claim is in any other status, or was already reminded on the sheet's today.
     */
    @Transactional
    public Claim remind(String sheetId, String user, long claimId) {
        Sheet sheet = sheets.lock(sheetId);
        LocalDate today = sheet.getToday();
        Claim claim = claim(sheetId, claimId);
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be reminded; only an OPEN or PENDING one can.");
        }
        if (today.equals(claim.getRemindedOn())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim was already reminded on " + today + ".");
        }
        LocalDate previous = claim.getRemindedOn();
        Integer gap = sheet.getEscalateAfter();
        boolean escalates = gap != null && previous != null && !claim.isEscalated()
                && !previous.plusDays(gap).isAfter(today);
        claim.remind(today);
        if (escalates) {
            claim.escalate();
        }
        Claim saved = claims.saveAndFlush(claim);
        Person person = person(sheetId, saved.getPersonId());
        audited("REMIND", sheetId, user, person, saved);
        if (escalates) {
            audited("ESCALATE", sheetId, user, person, saved);
        }
        return saved;
    }

