73	    /**
74	     * Make the claims a bulk settle settled the sheet's next settle batch: each carries its number.
75	     * Audited as BATCH_SETTLED with the batch number, how many claims it holds, and the frozen figures
76	     * of those of them SETTLED, added up.
77	     */
78	    @Transactional
79	    public Batch batch(String sheetId, String user, List<Long> claimIds) {
80	        int number = sheets.lock(sheetId).nextSettleBatch();
81	        List<Claim> batched = new ArrayList<>();
82	        BigDecimal total = BigDecimal.ZERO;
83	        for (Long id : claimIds) {
84	            Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow();
85	            claim.settledInBatch(number);
86	            if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
87	                total = total.add(claim.getSettledDue());
88	            }
89	            batched.add(claims.save(claim));
90	        }
91	        audit.recordOnCommit("BATCH_SETTLED sheet=" + sheetId + " by=" + user + " batch=" + number
92	                + " count=" + batched.size() + " total=" + total.setScale(2, RoundingMode.HALF_UP).toPlainString());
93	        return new Batch(number, batched);
94	    }
