102	    /**
103	     * The sheet's duplicate claims: for each person, date and amount with two or more claims (VOID and
104	     * DELETED claims left out), one line {@code <name> <date> <amount> x<count>}; people in list order,
105	     * then by date, then by amount.
106	     */
107	    @Transactional(readOnly = true)
108	    public List<String> duplicates(String sheetId) {
109	        Map<Long, Map<LocalDate, Map<BigDecimal, Integer>>> counts = new HashMap<>();
110	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
111	            if (claim.getStatus() == ClaimStatus.VOID || claim.getStatus() == ClaimStatus.DELETED) {
112	                continue;
113	            }
114	            counts.computeIfAbsent(claim.getPersonId(), id -> new TreeMap<>())
115	                    .computeIfAbsent(claim.getDate(), date -> new TreeMap<>())
116	                    .merge(claim.getAmount().setScale(2, RoundingMode.HALF_UP), 1, Integer::sum);
117	        }
118	        List<String> lines = new ArrayList<>();
119	        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
120	            counts.getOrDefault(person.getId(), Map.of()).forEach((date, amounts) -> amounts.forEach((amount, count) -> {
121	                if (count >= 2) {
122	                    lines.add(person.getName() + " " + date + " " + amount.toPlainString() + " x" + count);
123	                }
124	            }));
125	        }
126	        return lines;
127	    }
