153	    /**
154	     * Add a claim (see {@link #add(String, String, long, BigDecimal, LocalDate, String, String, String)}) with
155	     * its tags, comma separated (see {@link Claim#tagsOf}). CLAIM_ADDED ends with tags=&lt;tags, sorted and
156	     * comma separated&gt; when any were given.
157	     */
158	    @Transactional
159	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
160	            String corrects, String ref, String tags) {
161	        Rollups.Rollup before = rollups.take(sheetId);
162	        Person person = person(sheetId, personId);
163	        LocalDate dated = date != null ? date : sheets.load(sheetId).defaultClaimDate();
164	        Sheet sheet = sheets.lock(sheetId);
165	        int terms = terms(sheet, person, sheet.getToday());
166	        LocalDate dueBy = holidays.dueBy(sheetId, dated, terms);
167	        // Whether a new claim lands in a closed period is judged by its terms in calendar days from its date.
168	        periods.refuseIfClosed(sheetId, dated.plusDays(terms));
169	        refuseIfRetired(person, dated);
170	        refuseUnlessCorrects(sheetId, personId, amount, corrects, null);
171	        String referred = reference(ref);
172	        refuseIfReferred(sheetId, referred, null);
173	        Claim added = new Claim(sheetId, personId, money(amount), dated, terms, dueBy, clean(note), corrects);
174	        added.refer(referred);
175	        List<String> tagged = Claim.tagsOf(tags);
176	        added.tag(tagged);
177	        // A claim dated by the sheet's entry date is meant to be dated there: it is late by the sheet's today.
178	        LocalDate entered = date != null ? date : sheet.getToday();
179	        if (periods.softClosedOn(sheetId, entered) || periods.softClosedOn(sheetId, dueBy)) {
180	            added.markLateEntry();
181	        }
182	        Claim claim = claims.saveAndFlush(added);
183	        claim = logged(claim, user, person);
184	        audited("CLAIM_ADDED", sheetId, user, person, claim, claim.getNumber(),
185	                (referred != null ? " ref=" + referred : "")
186	                        + (tagged.isEmpty() ? "" : " tags=" + String.join(",", tagged)));
187	        if (claim.isLateEntry()) {
188	            audited("LATE_ENTRY", sheetId, user, person, claim);
189	        }
190	        rollups.audit(sheetId, user, before);
191	        return claim;
192	    }
