194	    /**
195	     * Change a claim's amount, date, note and the number it corrects; with no date it keeps its own. Only a DRAFT claim can be
196	     * edited: an OPEN one is changed by voiding it and adding a new one. It keeps the due-by fixed when it
197	     * was added, and so its period. Refused when the claim's due-by, or a new date plus its terms in
198	     * calendar days, is inside a closed period, or when it
199	     * would be a correction that does not name a SETTLED claim of the same person, or when its external
200	     * reference (null: kept as it is; blank: none) is already used by another claim on the sheet. Its tags
201	     * (null: kept as they are) are set from the comma separated text (see {@link Claim#tagsOf}).
202	     */
203	    @Transactional
204	    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
205	            String corrects, String ref, String tags) {
206	        Rollups.Rollup before = rollups.take(sheetId);
207	        sheets.lock(sheetId);
208	        Claim claim = claim(sheetId, claimId);
209	        refuseUnlessEditable(sheetId, user, claim);
210	        if (date != null) {
211	            refuseIfRetired(person(sheetId, claim.getPersonId()), date);
212	            if (!date.equals(claim.getDate())) {
213	                periods.refuseIfClosed(sheetId, date.plusDays(claim.getTerms()));
214	            }
215	        }
216	        if (!claim.getLines().isEmpty() && money(amount).compareTo(claim.getAmount()) != 0) {
217	            throw new ResponseStatusException(HttpStatus.CONFLICT,
218	                    "A claim with lines takes its amount from them: " + claim.getAmount().toPlainString() + ".");
219	        }
220	        refuseUnlessCorrects(sheetId, claim.getPersonId(), amount, corrects, claim.getId());
221	        String referred = ref == null ? claim.getRef() : reference(ref);
222	        refuseIfReferred(sheetId, referred, claim.getId());
223	        claim.refer(referred);
224	        if (tags != null) {
225	            claim.tag(Claim.tagsOf(tags));
226	        }
227	        claim.change(money(amount), date != null ? date : claim.getDate(), clean(note), corrects);
228	        claim.lockFor(null);
229	        claim.editedBy(user);
230	        Claim saved = claims.saveAndFlush(claim);
231	        audited("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved);
232	        rollups.audit(sheetId, user, before);
233	        return saved;
234	    }
