344	    /**
345	     * Settle a claim as {@link #move(String, String, long, ClaimStatus)} does, as of a date (null: the
346	     * sheet's today): its figure is frozen at the due it had at the end of that date, every change made
347	     * while the sheet's today was after it left out and that date standing in for the sheet's today, and
348	     * its audit record ends with the date. Refused for a date after the sheet's today, or one the claim
349	     * did not yet exist on.
350	     */
351	    @Transactional
352	    public Claim settle(String sheetId, String user, long claimId, LocalDate on) {
353	        return move(sheetId, user, claimId, ClaimStatus.SETTLED, null, on);
