356	    private Claim move(String sheetId, String user, long claimId, ClaimStatus next, String reason, LocalDate on) {
357	        // Every move takes the sheet's lock before reading the claim, so concurrent opens on the
358	        // sheet are serialised: each sees the other's committed claim and number.
359	        LocalDate today = sheets.lock(sheetId).getToday();
360	        Rollups.Rollup before = rollups.take(sheetId);
361	        Claim claim = claim(sheetId, claimId);
362	        periods.refuseIfClosed(sheetId, claim.getDueBy());
363	        String action = switch (next) {
364	            case OPEN -> "open";
365	            case SETTLED -> "settle";
366	            case VOID -> "void";
367	            case PENDING, DRAFT, DELETED, REVIEW -> throw new IllegalArgumentException("No move to " + next + ".");
368	        };
369	        if (!roles.permits(sheetId, user, action)) {
370	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " a claim.");
371	        }
372	        if (!claim.getStatus().canBecome(next)) {
373	            throw new ResponseStatusException(HttpStatus.CONFLICT,
374	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
375	        }
376	        boolean voidingSettled = next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
377	        if (voidingSettled) {
378	            refuseVoidingSettled(sheetId, user, claim, today);
379	        }
380	        String voidReason = next == ClaimStatus.VOID ? voidReasons.require(sheetId, reason) : null;
381	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(today)) {
382	            throw new ResponseStatusException(HttpStatus.CONFLICT,
383	                    "The claim is deferred until " + claim.getDeferredUntil() + ": it cannot be settled before then.");
384	        }
385	        if (next == ClaimStatus.SETTLED && claim.isOpenedOrEditedBy(user)) {
386	            throw new ResponseStatusException(HttpStatus.CONFLICT,
387	                    "The user who opened or last edited a claim cannot settle it.");
388	        }
389	        Person person = person(sheetId, claim.getPersonId());
390	        BigDecimal settledDue = next == ClaimStatus.SETTLED
391	                ? settlingOn(sheetId, claim, person, today, on)
392	                : null;
393	        if (next == ClaimStatus.OPEN && person.flaggedOn(today)
394	                && !Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
395	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
396	                    person.getName() + " is flagged (" + person.getFlagReason() + "): only a steward opens their claims.");
397	        }
398	        if (next == ClaimStatus.OPEN) {
399	            periods.refuseIfCapped(sheetId, claim);
400	            BigDecimal due = dues.due(claim, person.gradeOn(claim.getDate()));
401	            refuseUnnoted(sheetId, claim, due);
402	            if (overReviewThreshold(sheetId, claim, due)) {
403	                next = ClaimStatus.REVIEW;
404	            }
405	        }
406	        if (next == ClaimStatus.SETTLED) {
407	            refuseUnproved(sheetId, claim, person.gradeOn(claim.getDate()), settledDue);
408	        }
409	        if (next == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, person.gradeOn(today), settledDue)) {
410	            next = ClaimStatus.PENDING;
411	            settledDue = null;
412	        }
413	        claim.become(next);
414	        if (next == ClaimStatus.OPEN) {
415	            claim.number(periods.nextClaimNumber(sheetId, claim.getDueBy()));
416	        }
417	        if (next == ClaimStatus.OPEN || next == ClaimStatus.REVIEW) {
418	            claim.openedBy(user);
419	        }
420	        if (next == ClaimStatus.SETTLED) {
421	            claim.settleDue(settledDue);
422	        }
423	        if (next == ClaimStatus.VOID) {
424	            claim.voidedWith(voidReason);
425	        }
426	        Claim saved = logged(claims.saveAndFlush(claim), user, person);
427	        String event = switch (next) {
428	            case OPEN -> "CLAIM_OPENED";
429	            case SETTLED -> "CLAIM_SETTLED";
430	            case PENDING -> "CLAIM_PENDING";
431	            case REVIEW -> "CLAIM_REVIEW";
432	            case VOID -> "CLAIM_VOIDED";
433	            case DRAFT, DELETED -> throw new IllegalStateException();
434	        };
435	        String suffix = next == ClaimStatus.SETTLED
436	                ? " due=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE)
437	                : voidingSettled
438	                ? " reversed=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE)
439	                : "";
440	        if (voidReason != null) {
441	            suffix += " reason=" + voidReason;
442	        }
443	        if (next == ClaimStatus.SETTLED && on != null) {
444	            suffix += " on=" + on;
445	        }
446	        audited(event, sheetId, user, person, saved, saved.getNumber(), suffix);
447	        if (next == ClaimStatus.SETTLED) {
448	            watches.notifyWatchers(sheetId, user, person, saved.getNumber());
449	        }
450	        rollups.audit(sheetId, user, before);
451	        return saved;
452	    }
