454	    /**
455	     * The due a claim is settled at as of a date (null: the sheet's today, as it stands): on the sheet's
456	     * today its live settling figure; before it, its due as the claim stood at the end of that date,
457	     * read against the sheet as kept then. Refused for a date after the sheet's today, or one the claim
458	     * (or its person) was not yet kept on.
459	     */
460	    private BigDecimal settlingOn(String sheetId, Claim claim, Person person, LocalDate today, LocalDate on) {
461	        if (on == null || on.equals(today)) {
462	            return dues.settling(claim, person.gradeOn(claim.getDate()));
463	        }
464	        if (today == null || on.isAfter(today)) {
465	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
466	                    "A claim cannot be settled as of a date after today.");
467	        }
468	        ResponseStatusException notYet = new ResponseStatusException(HttpStatus.BAD_REQUEST,
469	                "The claim did not exist on " + on + ": it cannot be settled as of then.");
470	        SheetHistory.AsOf kept = history.at(sheetId, on).orElseThrow(() -> notYet);
471	        Claim then = kept.claims().get(claim.getId());
472	        Person personThen = then == null ? null : kept.people().get(then.getPersonId());
473	        if (then == null || personThen == null) {
474	            throw notYet;
475	        }
476	        return dues.due(then, personThen.gradeOn(then.getDate()), kept.basis());
477	    }
