488	        if (!claim.getStatus().canBecome(ClaimStatus.DELETED)) {
489	            throw new ResponseStatusException(HttpStatus.CONFLICT,
490	                    "A " + claim.getStatus() + " claim cannot be deleted; only a DRAFT can.");
491	        }
492	        claim.become(ClaimStatus.DELETED);
493	        claim.lockFor(null);
494	        Person person = person(sheetId, claim.getPersonId());
