500	    /**
501	     * Restore a DELETED claim to a DRAFT; refused when the claim is not DELETED, when the sheet's today
502	     * is not the day it was deleted, or when it is due by inside a closed period.
503	     */
504	    @Transactional
505	    public Claim restore(String sheetId, String user, long claimId) {
506	        LocalDate today = sheets.lock(sheetId).getToday();
507	        Claim claim = claim(sheetId, claimId);
508	        periods.refuseIfClosed(sheetId, claim.getDueBy());
509	        if (!claim.getStatus().canBecome(ClaimStatus.DRAFT)) {
510	            throw new ResponseStatusException(HttpStatus.CONFLICT,
511	                    "A " + claim.getStatus() + " claim cannot be restored; only a DELETED one can.");
512	        }
513	        if (today == null || !today.equals(claim.deletedOn())) {
514	            throw new ResponseStatusException(HttpStatus.CONFLICT,
515	                    "A claim can only be restored on the day it was deleted, " + claim.deletedOn() + ".");
516	        }
517	        if (claim.isCorrection()) {
518	            refuseUnlessCorrects(sheetId, claim.getPersonId(), claim.getAmount(), claim.getCorrects(), claim.getId());
519	        }
520	        claim.become(ClaimStatus.DRAFT);
521	        Person person = person(sheetId, claim.getPersonId());
522	        Claim saved = logged(claims.saveAndFlush(claim), user, person);
523	        audited("CLAIM_RESTORED", sheetId, user, person, saved);
524	        return saved;
525	    }
