527	    /**
528	     * Add a proof of a kind (null when none was chosen: a receipt) to a claim; refused when the claim is
529	     * SETTLED or VOID. The audit record carries the kind only when one was chosen.
530	     */
531	    @Transactional
532	    public Claim addProof(String sheetId, String user, long claimId, String kind) {
533	        sheets.lock(sheetId);
534	        Claim claim = claim(sheetId, claimId);
535	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
536	            throw new ResponseStatusException(HttpStatus.CONFLICT,
537	                    "A " + claim.getStatus() + " claim cannot take a proof.");
