565	    /**
566	     * Remind an OPEN or PENDING claim: the claim shows the sheet's today as its reminded date. Refused
567	     * when the claim is in any other status, or was already reminded on the sheet's today.
568	     */
569	    @Transactional
570	    public Claim remind(String sheetId, String user, long claimId) {
571	        Sheet sheet = sheets.lock(sheetId);
572	        LocalDate today = sheet.getToday();
573	        Claim claim = claim(sheetId, claimId);
574	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
575	            throw new ResponseStatusException(HttpStatus.CONFLICT,
576	                    "A " + claim.getStatus() + " claim cannot be reminded; only an OPEN or PENDING one can.");
577	        }
578	        if (today.equals(claim.getRemindedOn())) {
579	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim was already reminded on " + today + ".");
580	        }
581	        LocalDate previous = claim.getRemindedOn();
582	        Integer gap = sheet.getEscalateAfter();
583	        boolean escalates = gap != null && previous != null && !claim.isEscalated()
584	                && !previous.plusDays(gap).isAfter(today);
585	        claim.remind(today);
586	        if (escalates) {
587	            claim.escalate();
588	        }
589	        Claim saved = claims.saveAndFlush(claim);
590	        Person person = person(sheetId, saved.getPersonId());
591	        audited("REMIND", sheetId, user, person, saved);
592	        if (escalates) {
593	            audited("ESCALATE", sheetId, user, person, saved);
594	        }
595	        return saved;
596	    }
