672	    /**
673	     * Approve a PENDING claim: it becomes SETTLED, its due fixed at this moment at the figure a statement bound it to, else its live figure, with
674	     * the late charge it has then. Only a steward or the person's approver approves, and not the user who opened or last edited the claim.
675	     */
676	    @Transactional
677	    public Claim approve(String sheetId, String user, long claimId) {
678	        sheets.lock(sheetId);
679	        Rollups.Rollup before = rollups.take(sheetId);
680	        Claim claim = pending(sheetId, user, claimId);
681	        if (claim.isOpenedOrEditedBy(user)) {
682	            throw new ResponseStatusException(HttpStatus.CONFLICT,
683	                    "The user who opened or last edited a claim cannot approve it.");
684	        }
685	        Person person = person(sheetId, claim.getPersonId());
686	        BigDecimal approvedDue = dues.approving(claim, person.gradeOn(claim.getDate()));
687	        refuseUnproved(sheetId, claim, person.gradeOn(claim.getDate()), approvedDue);
688	        claim.settleDue(approvedDue);
