690	        Claim saved = logged(claims.saveAndFlush(claim), user, person);
691	        audited("CLAIM_APPROVED", sheetId, user, person, saved, saved.getNumber(),
692	                " due=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE));
