786	    /**
787	     * Reassign a claim as {@link #reassign(String, String, long, long)} does; when {@code toOwn} is set,
788	     * a claim already the new person's is not refused but reassigned to them again (as a bulk
789	     * reassign does to each selected claim).
790	     */
791	    @Transactional
792	    public Claim reassign(String sheetId, String user, long claimId, long personId, boolean toOwn) {
793	        sheets.lock(sheetId);
794	        Rollups.Rollup before = rollups.take(sheetId);
795	        Claim claim = claim(sheetId, claimId);
796	        if (!roles.permits(sheetId, user, "reassign")) {
797	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reassign a claim.");
798	        }
799	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
800	            throw new ResponseStatusException(HttpStatus.CONFLICT,
801	                    "A " + claim.getStatus() + " claim cannot be reassigned.");
802	        }
803	        periods.refuseIfClosed(sheetId, claim.getDueBy());
804	        Person from = person(sheetId, claim.getPersonId());
805	        Person to = person(sheetId, personId);
806	        if (!toOwn && from.getId().equals(to.getId())) {
807	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s.");
808	        }
809	        refuseIfRetired(to, claim.getDate());
810	        refuseUnlessCorrects(sheetId, from.getId(), claim.getAmount(), claim.getCorrects(), claim.getId());
811	        claim.reassign(to.getId());
812	        claim.unbind();
813	        if (claim.getNumber() != null) {
814	            claim.number(periods.nextClaimNumber(sheetId, claim.getDueBy()));
815	        }
816	        Claim saved = claims.saveAndFlush(claim);
817	        audited("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber(),
818	                " from=" + from.getName() + " to=" + to.getName());
819	        rollups.audit(sheetId, user, before);
820	        return saved;
821	    }
