856	    /**
857	     * Split an amount (above 0.00 and below the claim's amount) off an OPEN claim: it keeps the rest
858	     * of its amount and loses any figure a statement bound it to; a new OPEN claim with the split-off
859	     * amount, the same date and note, the next number, opened by the user and due by a date fixed now
860	     * from the terms in force on the sheet's today (the day it is created), names the original's number as the one it was split from;
861	     * it is a late entry when that due-by is inside a soft-closed period. Refused when the claim is not
862	     * OPEN, is deferred on the sheet's today, or when its due-by or the new claim's is inside a closed
863	     * period.
864	     */
865	    @Transactional
866	    public Split split(String sheetId, String user, long claimId, BigDecimal amount) {
867	        Sheet sheet = sheets.lock(sheetId);
868	        LocalDate today = sheet.getToday();
869	        Rollups.Rollup before = rollups.take(sheetId);
870	        Claim claim = claim(sheetId, claimId);
871	        if (claim.getStatus() != ClaimStatus.OPEN) {
872	            throw new ResponseStatusException(HttpStatus.CONFLICT,
873	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one can.");
874	        }
875	        if (claim.isDeferredOn(today)) {
876	            throw new ResponseStatusException(HttpStatus.CONFLICT,
877	                    "The claim is deferred until " + claim.getDeferredUntil() + ": it cannot be split.");
878	        }
879	        periods.refuseIfClosed(sheetId, claim.getDueBy());
880	        BigDecimal off = money(amount);
881	        if (off.signum() <= 0 || off.compareTo(claim.getAmount()) >= 0) {
882	            throw new ResponseStatusException(HttpStatus.CONFLICT,
883	                    "The amount split off must be above 0.00 and below the claim's " + claim.getAmount().toPlainString() + ".");
884	        }
885	        Person person = person(sheetId, claim.getPersonId());
886	        int terms = terms(sheet, person, today);
887	        LocalDate dueBy = holidays.dueBy(sheetId, claim.getDate(), terms);
888	        periods.refuseIfClosed(sheetId, dueBy);
889	        Claim split = claim.split(off, terms, dueBy);
890	        if (periods.softClosedOn(sheetId, dueBy)) {
891	            split.markLateEntry();
892	        }
893	        split.number(periods.nextClaimNumber(sheetId, split.getDueBy()));
894	        split.openedBy(user);
895	        Claim original = claims.saveAndFlush(claim);
896	        split = logged(claims.saveAndFlush(split), user, person);
897	        audited("CLAIM_SPLIT", sheetId, user, person, original, original.getNumber(), " into=" + split.getNumber());
898	        audited("CLAIM_OPENED", sheetId, user, person, split);
899	        rollups.audit(sheetId, user, before);
900	        return new Split(original, split);
901	    }
