917	     * Refuse when settling an OPEN claim would be refused: the user's role may not settle, the claim
918	     * is not OPEN, is due by inside a closed period, is deferred on the sheet's today, was opened or
919	     * last edited by the user, or its due is above the proof threshold with no proof. Taken before a
920	     * part-settle splits the claim, so a part-settle such a settle would refuse writes nothing.
921	     */
922	    @Transactional(readOnly = true)
923	    public void refuseSettling(String sheetId, String user, long claimId) {
924	        LocalDate today = sheets.load(sheetId).getToday();
925	        Claim claim = claim(sheetId, claimId);
926	        periods.refuseIfClosed(sheetId, claim.getDueBy());
927	        if (!roles.permits(sheetId, user, "settle")) {
928	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not settle a claim.");
929	        }
930	        if (claim.getStatus() != ClaimStatus.OPEN) {
931	            throw new ResponseStatusException(HttpStatus.CONFLICT,
932	                    "A " + claim.getStatus() + " claim cannot be part-settled; only an OPEN one can.");
933	        }
934	        if (claim.isDeferredOn(today)) {
935	            throw new ResponseStatusException(HttpStatus.CONFLICT,
936	                    "The claim is deferred until " + claim.getDeferredUntil() + ": it cannot be settled before then.");
937	        }
938	        if (claim.isOpenedOrEditedBy(user)) {
939	            throw new ResponseStatusException(HttpStatus.CONFLICT,
940	                    "The user who opened or last edited a claim cannot settle it.");
941	        }
942	        Person person = person(sheetId, claim.getPersonId());
943	        String grade = person.gradeOn(claim.getDate());
944	        refuseUnproved(sheetId, claim, grade, dues.settling(claim, grade));
