947	    /**
948	     * The PENDING claim a steward, or its person's approver, approves or rejects; refused when it is not
949	     * PENDING, when its date is inside a closed period, or when the user is neither.
950	     */
951	    private Claim pending(String sheetId, String user, long claimId) {
952	        Claim claim = claim(sheetId, claimId);
953	        periods.refuseIfClosed(sheetId, claim.getDueBy());
954	        if (claim.getStatus() != ClaimStatus.PENDING) {
955	            throw new ResponseStatusException(HttpStatus.CONFLICT,
956	                    "A " + claim.getStatus() + " claim is not pending approval.");
957	        }
958	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))
959	                && !user.equals(person(sheetId, claim.getPersonId()).getApprover())) {
960	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
961	                    "Only a steward or the person's approver approves or rejects a claim.");
962	        }
963	        return claim;
