966	    /**
967	     * Refuse settling or approving a claim whose due is above the proof threshold in force on the
968	     * claim's date (its person's grade's, the grade in force then, when one is set, else the sheet's; a
969	     * due of n/a is within any threshold) with no proofs, or, while the sheet has proof kinds, with no
970	     * proof of one of them.
971	     */
972	    private void refuseUnproved(String sheetId, Claim claim, String grade, BigDecimal due) {
973	        Sheet sheet = sheets.load(sheetId);
974	        BigDecimal threshold = sheet.proofThresholdFor(grade, claim.getDate());
975	        if (threshold == null || due == null || due.compareTo(threshold) <= 0) {
976	            return;
977	        }
978	        if (claim.getProofs() == 0) {
979	            throw new ResponseStatusException(HttpStatus.CONFLICT,
980	                    "The claim's due is above the proof threshold of " + threshold.toPlainString()
981	                            + ": it needs a proof before it is settled.");
982	        }
983	        for (String kind : sheet.proofKindList()) {
984	            if (claim.getProofs(kind) == 0) {
985	                throw new ResponseStatusException(HttpStatus.CONFLICT,
986	                        "The claim's due is above the proof threshold of " + threshold.toPlainString()
987	                                + ": it needs a " + kind + " proof before it is settled.");
988	            }
989	        }
990	    }
