992	    /**
993	     * Refuse opening a claim with an empty note whose due is above the sheet's note threshold in force
994	     * on the claim's date (a due of n/a is within any threshold).
995	     */
996	    private void refuseUnnoted(String sheetId, Claim claim, BigDecimal due) {
997	        BigDecimal threshold = sheets.load(sheetId).noteThresholdOn(claim.getDate());
998	        if ((claim.getNote() == null || claim.getNote().isBlank()) && threshold != null && due != null
999	                && due.compareTo(threshold) > 0) {
1000	            throw new ResponseStatusException(HttpStatus.CONFLICT,
1001	                    "The claim's due is above the note threshold of " + threshold.toPlainString()
1002	                            + ": it needs a note before it is opened.");
1003	        }
1004	    }
