1006	    /**
1007	     * Refuse voiding a SETTLED claim unless the user acts as a steward and the sheet's today is no more
1008	     * than {@link ClaimStatus#VOID_SETTLED_DAYS} days after the claim's settlement in its status log.
1009	     */
1010	    private void refuseVoidingSettled(String sheetId, String user, Claim claim, LocalDate today) {
1011	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
1012	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward voids a SETTLED claim.");
1013	        }
1014	        LocalDate settledOn = claim.settledOn();
1015	        if (settledOn == null || today == null || today.isAfter(settledOn.plusDays(ClaimStatus.VOID_SETTLED_DAYS))) {
1016	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A SETTLED claim can only be voided within "
1017	                    + ClaimStatus.VOID_SETTLED_DAYS + " days of its settlement.");
