1021	    /** Whether a claim's due is above the sheet's review threshold in force on the claim's date. */
1022	    private boolean overReviewThreshold(String sheetId, Claim claim, BigDecimal due) {
1023	        BigDecimal threshold = sheets.load(sheetId).reviewThresholdOn(claim.getDate());
1024	        return threshold != null && due != null && due.compareTo(threshold) > 0;
1025	    }
