1029	     * today: its person's grade's when one is set, else the sheet's.
1030	     */
1031	    private boolean overClerkLimit(String sheetId, String user, String grade, BigDecimal due) {
1032	        BigDecimal limit = sheets.clerkLimit(sheetId, grade);
1033	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
1034	            return false;
1035	        }
1036	        return Role.CLERK.equals(roles.roleOf(sheetId, user));
1037	    }
1038	
1039	    /**
1040	     * Refuse a correction (an amount below 0.00) unless it names, by number, a SETTLED claim of the
1041	     * same person, and unless it is no more than what remains of that claim: its amount less the
1042	     * amounts of the corrections already made against it (VOID or DELETED ones, and the claim
1043	     * {@code self} itself, left out); and refuse naming a claim to correct on any other claim.
1044	     */
1045	    private void refuseUnlessCorrects(String sheetId, long personId, BigDecimal amount, String corrects, Long self) {
1046	        if (amount.signum() >= 0) {
1047	            if (corrects != null) {
1048	                throw new ResponseStatusException(HttpStatus.CONFLICT,
1049	                        "Only a correction, with an amount below 0.00, names a claim it corrects.");
1050	            }
1051	            return;
1052	        }
1053	        Claim target = corrects == null ? null : claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
1054	                .filter(corrected -> corrected.getStatus() == ClaimStatus.SETTLED)
1055	                .orElse(null);
1056	        if (target == null) {
1057	            throw new ResponseStatusException(HttpStatus.CONFLICT,
1058	                    "A correction must name the number of a SETTLED claim of the same person.");
1059	        }
1060	        BigDecimal remains = target.getAmount();
1061	        for (Claim made : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId)) {
1062	            if (corrects.equals(made.getCorrects()) && !made.getId().equals(self)
1063	                    && made.getStatus() != ClaimStatus.VOID && made.getStatus() != ClaimStatus.DELETED) {
1064	                remains = remains.add(made.getAmount());
1065	            }
1066	        }
1067	        if (money(amount).negate().compareTo(remains) > 0) {
1068	            throw new ResponseStatusException(HttpStatus.CONFLICT,
1069	                    "A correction may not exceed what remains of " + corrects + ": "
1070	                            + money(remains.max(BigDecimal.ZERO)).toPlainString() + ".");
1071	        }
1072	    }
1073	
1074	    /** Refuse a claim dated after its person's retirement, or after the from and before the to of a past one. */
1075	    private static void refuseIfRetired(Person person, LocalDate date) {
1076	        if (!person.canClaimOn(date)) {
1077	            throw new ResponseStatusException(HttpStatus.CONFLICT,
1078	                    person.getName() + " is retired from " + person.getRetiredFrom() + ": a claim cannot be dated after it.");
1079	        }
1080	        Retirement past = person.pastRetirementBarring(date);
1081	        if (past != null) {
1082	            throw new ResponseStatusException(HttpStatus.CONFLICT, person.getName() + " was retired from "
1083	                    + past.getFromDate() + " to " + past.getToDate() + ": a claim cannot be dated within it.");
1084	        }
1085	    }
1086	
1087	    /**
1088	     * The claim's timeline: the audit lines about it, newest first, as the file holds them — those
1089	     * carrying its number, or for a claim with no number those naming its person, amount and date.
1090	     */
1091	    @Transactional(readOnly = true)
1092	    public List<String> timeline(String sheetId, long claimId) {
1093	        Claim claim = claim(sheetId, claimId);
1094	        Person person = person(sheetId, claim.getPersonId());
1095	        return audit.linesOfClaim(sheetId, claim.getNumber(), person.getName(),
1096	                claim.getAmount().toPlainString(), claim.getDate().toString());
1097	    }
1098	
1099	    private Claim claim(String sheetId, long claimId) {
1100	        return claims.findByIdAndSheetId(claimId, sheetId)
1101	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
1102	    }
1103	
1104	    /**
1105	     * The terms, in business days, a claim of the person created on a day (the sheet's today then) is fixed
1106	     * with, whatever its date: the first of the person's own terms, their grade's terms and the sheet's terms
1107	     * in force on that day.
1108	     */
1109	    private static int terms(Sheet sheet, Person person, LocalDate date) {
1110	        Integer own = person.termsOn(date);
1111	        return own != null ? own : sheet.termsFor(person.gradeOn(date), date);
1112	    }
1113	
1114	    private Person person(String sheetId, long personId) {
1115	        return people.findByIdAndSheetId(personId, sheetId)
1116	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
1117	    }
1118	
1119	    /**
1120	     * Add a line to the claim's status log for the status it now has: by the user, on the sheet's
1121	     * today, with its due as computed now.
1122	     */
1123	    private Claim logged(Claim claim, String user, Person person) {
1124	        claim.logged(user, sheets.today(claim.getSheetId()), dues.due(claim, person.gradeOn(claim.getDate())));
1125	        return claims.saveAndFlush(claim);
1126	    }
1127	
