1136	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
1137	                + (number != null ? " number=" + number : "") + suffix);
1138	    }
1139	
1140	    /** The due figure a claim shows, without its late charge (see {@link Dues#figure}). */
1141	    public BigDecimal figure(Claim claim, String grade) {
1142	        return dues.figure(claim, grade);
1143	    }
1144	
1145	    /** The due a claim shows, with its late charge (see {@link Dues#due}). */
1146	    public BigDecimal due(Claim claim, String grade) {
1147	        return dues.due(claim, grade);
1148	    }
1149	
1150	    /** Refuse a reference already used on the sheet by a claim other than the one given (null: any). */
1151	    private void refuseIfReferred(String sheetId, String ref, Long self) {
1152	        if (ref == null) {
1153	            return;
1154	        }
1155	        claims.findBySheetIdAndRefKey(sheetId, Claim.keyOf(ref))
1156	                .filter((other) -> !other.getId().equals(self))
1157	                .ifPresent((other) -> {
