    /** The late percent in force on the sheet's today, with two decimals. */
    public BigDecimal getLatePct() {
        return latePctOn(today);
    }

    /** The late percent in force on a date, with two decimals. */
    public BigDecimal latePctOn(LocalDate date) {
        return decimal(valueOn(LATE_PCT, date, plain(latePct)));
    }

    /** The key a grade's own terms are recorded under. */
    public static String gradeTermsKey(String grade) {
        return TERMS + "-" + grade;
    }

    /** The key a grade's grace is recorded under. */
    public static String gradeGraceKey(String grade) {
        return GRACE + "-" + grade;
    }

    /** The key a grade's clerk limit is recorded under. */
    public static String gradeClerkLimitKey(String grade) {
        return CLERK_LIMIT + "-" + grade;
    }

    /** The key a grade's proof threshold is recorded under. */
    public static String gradeProofThresholdKey(String grade) {
        return PROOF_THRESHOLD + "-" + grade;
    }

    /** A grade's grace values (see {@link #history}), none before every from-date. */
    public List<DatedSetting> gradeGraceHistory(String grade) {
        return history(gradeGraceKey(grade), null);
    }

    /**
     * Record a setting's value (null: none) from a date, keeping the values already recorded; a value
     * already recorded from that date is replaced.
     */
    public void record(String key, LocalDate from, String value) {
        dated.removeIf(d -> d.getKey().equals(key) && d.getFromDate().equals(from));
        dated.add(new DatedSetting(key, from, value));
    }

    /**
     * A setting's values: its starting value (with no from-date) and then each recorded from a date,
     * by from-date.
     */
    public List<DatedSetting> history(String key, String start) {
        List<DatedSetting> all = new ArrayList<>();
        all.add(new DatedSetting(key, null, start));
        dated.stream().filter(d -> d.getKey().equals(key))
                .sorted(Comparator.comparing(DatedSetting::getFromDate)).forEach(all::add);
        return all;
    }

    /** Every value recorded for a setting from a date, whatever its key. */
    public List<DatedSetting> getDated() {
        return List.copyOf(dated);
    }

    /**
     * The sheet as it stood on a past date, held in no store: its starting values and permissions as
     * now, that date as its today, and the values recorded from a date and the policy date it had then.
     */
    public Sheet asOf(LocalDate day, List<DatedSetting> datedThen, LocalDate policyDateThen) {
        Sheet then = new Sheet(id, createdAt, day);
        then.lastClaimNumber = lastClaimNumber;
        then.clerkLimit = clerkLimit;
        then.cap = cap;
        then.proofThreshold = proofThreshold;
        then.floor = floor;
        then.terms = terms;
        then.termsA = termsA;
        then.termsB = termsB;
        then.termsC = termsC;
        then.latePct = latePct;
        then.policyDate = policyDateThen;
        then.periodNumberingFrom = periodNumberingFrom;
        then.graceDays = graceDays;
        then.entryDate = entryDate;
        then.pot = pot;
        then.alertThreshold = alertThreshold;
        then.escalateAfter = escalateAfter;
        then.reviewSla = reviewSla;
        then.proofKinds = proofKinds;
        then.defaultGrade = defaultGrade;
        then.fiscalStartMonth = fiscalStartMonth;
        then.parentId = parentId;
        then.clonedFrom = clonedFrom;
        then.archived = archived;
        then.dated = new ArrayList<>(datedThen);
        then.permissions = new HashMap<>(permissions);
        then.lastFiscalClaimNumbers = new HashMap<>(lastFiscalClaimNumbers);
        return then;
    }

    /** The floor's values (see {@link #history}). */
    public List<DatedSetting> floorHistory() {
        return history(FLOOR, plain(floor));
    }

    /** The rounding mode's values (see {@link #history}), none before every from-date. */
    public List<DatedSetting> roundingHistory() {
        return history(ROUNDING, null);
    }

    /** The late percent's values (see {@link #history}). */
    public List<DatedSetting> latePctHistory() {
        return history(LATE_PCT, plain(latePct));
    }

    /**
     * A setting's value in force on a date: the one recorded with the latest from-date on or before
     * it (which may be null, for none), else the starting value.
     */
    private String valueOn(String key, LocalDate date, String start) {
        Optional<DatedSetting> recorded = dated.stream()
                .filter(d -> d.getKey().equals(key) && !d.getFromDate().isAfter(date))
                .max(Comparator.comparing(DatedSetting::getFromDate));
        return recorded.isPresent() ? recorded.get().getValue() : start;
    }

    private static String plain(BigDecimal value) {
        return value == null ? null : value.toPlainString();
    }

    private static BigDecimal decimal(String value) {
        return value == null ? null : new BigDecimal(value);
    }

    /** The policy date as set; null when blank (the sheet's today is then the policy date). */
    public LocalDate getPolicyDate() {
        return policyDate;
    }

    public void setPolicyDate(LocalDate policyDate) {
        this.policyDate = policyDate;
    }

    /**
     * How the live figures of a claim dated on a date round: by the rounding mode in force on that date
     * when there is one, else half up when the date is before the
     * policy date (the sheet's today when none is set), else half to even.
     */
    public RoundingMode roundingOn(LocalDate date) {
        RoundingMode mode = roundingModeOn(date);
        if (mode != null) {
            return mode;
        }
        LocalDate policy = policyDate == null ? today : policyDate;
        return date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** The rounding mode in force on the sheet's today (half-up or half-even); null when there is none. */
    public String getRounding() {
        return valueOn(ROUNDING, today, null);
    }

    /** The rounding mode in force on a date; null when there is none (the policy date then decides). */
    public RoundingMode roundingModeOn(LocalDate date) {
        String value = valueOn(ROUNDING, date, null);
        if (value == null) {
            return null;
        }
        return switch (value) {
            case "half-up" -> RoundingMode.HALF_UP;
            case "half-even" -> RoundingMode.HALF_EVEN;
            default -> null;
        };
    }

    /** The period-numbering-from date as set; null when blank (off). */
    public LocalDate getPeriodNumberingFrom() {
        return periodNumberingFrom;
    }

    public void setPeriodNumberingFrom(LocalDate periodNumberingFrom) {
        this.periodNumberingFrom = periodNumberingFrom;
    }

    /** The grace days as set; null when blank (off). */
    public Integer getGraceDays() {
        return graceDays;
    }

    public void setGraceDays(Integer graceDays) {
        this.graceDays = graceDays;
    }

    /** The entry date as set; null when blank (off). */
    public LocalDate getEntryDate() {
        return entryDate;
    }

    public void setEntryDate(LocalDate entryDate) {
        this.entryDate = entryDate;
    }

    /** The pot as set, with two decimals; null when blank (none). */
    public BigDecimal getPot() {
        return pot;
    }

    public void setPot(BigDecimal pot) {
        this.pot = pot;
    }

    /** The alert threshold as set, with two decimals; null when blank (off). */
    public BigDecimal getAlertThreshold() {
        return alertThreshold;
    }

    public void setAlertThreshold(BigDecimal alertThreshold) {
        this.alertThreshold = alertThreshold;
    }

    /** The escalation gap in days; null when blank (off). */
    public Integer getEscalateAfter() {
        return escalateAfter;
    }

    public void setEscalateAfter(Integer escalateAfter) {
        this.escalateAfter = escalateAfter;
    }

    /** The review SLA in days; null when blank (none). */
    public Integer getReviewSla() {
        return reviewSla;
    }

    public void setReviewSla(Integer reviewSla) {
        this.reviewSla = reviewSla;
    }

    /** The proof kinds as set, comma separated; null when blank (none). */
    public String getProofKinds() {
        return proofKinds;
    }

    public void setProofKinds(String proofKinds) {
        this.proofKinds = proofKinds;
    }

    /** The default grade as set; null when blank (A). */
    public String getDefaultGrade() {
        return defaultGrade;
    }

    public void setDefaultGrade(String defaultGrade) {
        this.defaultGrade = defaultGrade;
    }

    /** The grade a person added without one is given: the default grade, else A. */
    public String defaultGradeInForce() {
        return defaultGrade == null ? "A" : defaultGrade;
    }

    /** The proof kinds as a list; empty when there are none. */
    public List<String> proofKindList() {
        return proofKinds == null ? List.of() : Arrays.asList(proofKinds.split(","));
    }

    /** The month, 1 to 12, the sheet's fiscal year starts in. */
    public int getFiscalStartMonth() {
        return fiscalStartMonth;
    }

    public void setFiscalStartMonth(int fiscalStartMonth) {
        this.fiscalStartMonth = fiscalStartMonth;
    }

    /** The first day of the fiscal year named after a calendar year: the sheet's start month's first day in it. */
    public LocalDate fiscalYearStart(int year) {
        return LocalDate.of(year, fiscalStartMonth, 1);
    }

    /** The parent sheet's id; null when none. */
    public String getParentId() {
        return parentId;
    }

    public void setParentId(String parentId) {
        this.parentId = parentId;
    }

    /** The id of the sheet this one was cloned from; null when not cloned. */
    public String getClonedFrom() {
        return clonedFrom;
    }

    /** The date a new claim with no date of its own is given: the entry date while set, else the sheet's today. */
    public LocalDate defaultClaimDate() {
        return entryDate != null ? entryDate : today;
    }

    /** Whether a claim opened now is numbered within its period: the setting is a date on or before today. */
    public boolean numbersByPeriod() {
        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
    }

    /** Give out the sheet's next number for a claim in no period: 1 for the first, then 2, and so on. */
    public int nextUnperiodClaimNumber() {
        return ++lastUnperiodClaimNumber;
    }

    /** The last settle batch number given out; 0 when there has been none. */
    public int getLastSettleBatch() {
        return lastSettleBatch;
    }

    /** Give out the sheet's next settle batch number: 1 for the first, then 2, and so on. */
    public int nextSettleBatch() {
        return ++lastSettleBatch;
    }

    /** The last claim number the sheet gave out; 0 before any claim is opened. */
    public int getLastClaimNumber() {
        return lastClaimNumber;
    }

    /** The year the fiscal year a date falls in is named after: the calendar year it starts in. */
    public int fiscalYearOf(LocalDate date) {
        return date.getMonthValue() >= fiscalStartMonth ? date.getYear() : date.getYear() - 1;
    }

    /** The last claim number the sheet gave out in a fiscal year; 0 before any. */
    public int getLastClaimNumberIn(int fiscalYear) {
        return lastFiscalClaimNumbers.getOrDefault(fiscalYear, 0);
    }

    /** Give out the next claim number in a fiscal year after the last given in it anywhere in the sheet's tree. */
    public int nextClaimNumberIn(int fiscalYear, int lastInTree) {
        int next = Math.max(getLastClaimNumberIn(fiscalYear), lastInTree) + 1;
        lastFiscalClaimNumbers.put(fiscalYear, next);
        return next;
    }

    /** The roles set for an action, comma separated; null when it keeps its standing rule. */
    public String getPermission(String action) {
        return permissions.get(action);
    }

    /** Set the roles that may take an action (null: the standing rule). */
    public void setPermission(String action, String roles) {
        if (roles == null) {
            permissions.remove(action);
        } else {
            permissions.put(action, roles);
        }
    }

    /** Whether a role may take an action: the roles set for it, else its standing rule. */
    public boolean permits(String action, String role) {
        String roles = permissions.getOrDefault(action, STANDING_PERMISSIONS.get(action));
        return Arrays.asList(roles.split(",")).contains(role);
    }
}

package net.officefloor.hq.app.person;


@RestController
@RequestMapping("/api/sheets/{sheetId}/people")
@Validated
public class PersonController {

    /**
     * What the screen is told about a person, with their statement count, and the last statement's
     * due-total (null when n/a or none taken) and date (null when none taken), and the date they are
     * retired from (null when not retired), whether they have any hold, their holds, and the ids of their patrons
     * in the order they were named, and whether their name or an alias is in use on another sheet of the
     * sheet's tree (clashing), and the sheet they were last transferred from (null when never), and their
     * flag's reason and last day (both null when never flagged), and their approver (null when none).
     * Their grades are listed by the date each is in force from, the first with none (from the
     * beginning of time). Their terms are their own from the beginning of time; the own terms recorded
     * since are listed by the date each is in force from.
     */
    public record PersonView(long id, String name, List<GradeView> grades, Integer terms, List<TermsView> termsFrom,
            String contact, List<String> tags,
            List<String> tagsUsed, long version, int statementCount,
            String statementTotal, LocalDate statementDate, LocalDate retiredFrom, List<RetirementView> retirements, boolean held,
            List<HoldView> holds, List<Long> patronIds, List<String> aliases, boolean clashing,
            String originSheetId, List<SnapshotView> snapshots, List<StatementLineView> statementLines,
            String flagReason, LocalDate flagUntil, String approver) {

        public static PersonView of(Person person) {
            return of(person, false);
        }

        public static PersonView of(Person person, boolean clashing) {
            List<GradeView> grades = new ArrayList<>();
            grades.add(new GradeView(person.getGrade(), null));
            person.getGradesFrom().forEach((from, grade) -> grades.add(new GradeView(grade, from)));
            List<TermsView> termsFrom = new ArrayList<>();
            person.getTermsFrom().forEach((from, terms) -> termsFrom.add(new TermsView(terms, from)));
            return new PersonView(person.getId(), person.getName(), grades, person.getTerms(), termsFrom,
                    person.getContact(),
                    person.getTags(), person.getTagsUsed(), person.getVersion(),
                    person.getStatementCount(),
                    person.getStatementTotal() == null ? null : person.getStatementTotal().toPlainString(),
                    person.getStatementDate(), person.getRetiredFrom(),
                    person.getRetirements().stream().map(r -> new RetirementView(r.getFromDate(), r.getToDate())).toList(),
                    person.isHeld(),
                    person.getHolds().stream().map(hold -> new HoldView(hold.getFromDate(), hold.getToDate())).toList(),
                    person.getPatronIds(), person.getAliases(), clashing, person.getOriginSheetId(),
                    person.getSnapshots().stream()
                            .map(snapshot -> new SnapshotView(snapshot.getAsOf(), Rollups.shown(snapshot.getDueTotal())))
                            .toList(),
                    person.getStatements().stream()
                            .map(statement -> new StatementLineView(statement.getTakenOn(),
                                    Rollups.shown(statement.getTotal())))
                            .toList(),
                    person.getFlagReason(), person.getFlagUntil(), person.getApprover());
        }
    }

    /** A past retirement of a person, from its date to the day they were unretired. */
    public record RetirementView(LocalDate from, LocalDate to) {
    }

    /** A snapshot line of a person: the day being left and their due-total on it (n/a when no rate applied). */
    public record SnapshotView(LocalDate asOf, String dueTotal) {
    }

    /** A statement line of a person: the date it was taken as of and its due-total (n/a when no rate applied). */
    public record StatementLineView(LocalDate date, String dueTotal) {
    }

    /** A hold on a person, from a date to a date (null: no end). */
    public record HoldView(LocalDate from, LocalDate to) {
    }

    /** A grade a person has, from a date (null: from the beginning of time). */
    public record GradeView(String grade, LocalDate from) {
    }

    /** Own terms a person has from a date, in days (null: none of their own). */
    public record TermsView(Integer terms, LocalDate from) {
    }

    /**
     * A person's values as entered on the form: a name is required, the grade is A, B or C. On an edit
     * the grade is recorded from its date (none: the sheet's today); a person's first grade applies
     * from the beginning of time. Their own terms are a whole number of days, none for no terms of
     * their own; on an edit they are recorded from their date (none: from the beginning of time). A contact is kept trimmed and lower-cased, blank for none. Tags are comma separated
     * (blank: none; none at all keep the person's own). An edit says whether the
     * grade was chosen on the form (it is then recorded from its date even when already in force there), and whether the
     * terms and the contact were typed on the form (PERSON_EDITED then carries them), and carries the version of the person the form loaded.
     */
    public record PersonForm(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            LocalDate gradeFrom,
            @PositiveOrZero @Max(36500) Integer terms,
            LocalDate termsFrom,
            @Size(max = 200) String contact,
            boolean termsGiven,
            boolean contactGiven,
            Long version,
            @Size(max = 1000) String tags,
            boolean gradeGiven) {
    }

    /** The people selected to be given a grade together, the grade, and the date it is in force from (none: the sheet's today). */
    public record BulkGradeForm(
            @NotNull @Size(min = 1, max = 1000) List<@NotNull Long> personIds,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            LocalDate from) {
    }

    /** A grade chosen on a person's row, from the version of the person the row shows. */
    public record RowGradeForm(@NotNull @Pattern(regexp = "[ABC]") String grade, @NotNull Long version) {
    }

    /** The people selected to be retired together, and the date they are retired from (none: the sheet's today). */
    public record BulkRetireForm(
            @NotNull @Size(min = 1, max = 1000) List<@NotNull Long> personIds,
            LocalDate from) {
    }

    /** The import box's text: lines of name,grade,terms,contact. */
    public record ImportForm(@NotNull @Size(max = 200_000) String text) {
    }

    private final PersonService service;
    private final ImportService imports;
    private final BulkGradeService bulkGrade;
    private final BulkRetireService bulkRetire;
    private final WatchService watches;
    private final MergeService merges;
    private final TransferService transfers;
    private final SheetHistory history;

    public PersonController(PersonService service, ImportService imports, BulkGradeService bulkGrade,
            BulkRetireService bulkRetire, WatchService watches,
            MergeService merges, TransferService transfers, SheetHistory history) {
        this.service = service;
        this.imports = imports;
        this.bulkGrade = bulkGrade;
        this.bulkRetire = bulkRetire;
        this.watches = watches;
        this.merges = merges;
        this.transfers = transfers;
        this.history = history;
    }

    /** The sheet's people in list order; with an as-of date, as they stood at the end of it. */
    @GetMapping
    public List<PersonView> list(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) String asOf) {
        return history.views(sheetId, AsOfGuard.date(asOf)).map(SheetHistory.Views::people)
                .orElseGet(() -> {
                    Set<Long> clashing = service.clashing(sheetId);
                    return service.list(sheetId).stream()
                            .map(person -> PersonView.of(person, clashing.contains(person.getId()))).toList();
                });
    }

    /** Add a person to the sheet. */
    @PostMapping
    public PersonView add(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid PersonForm form) {
        return view(service.add(sheetId, SignedIn.name(user), form.name(), form.grade(), form.terms(),
                form.contact(), form.tags()));
    }

    /** The people an import added and those it updated, each in the order of their lines. */
    public record ImportView(List<PersonView> added, List<PersonView> updated) {
    }

    /**
     * Add a person per imported line, in order, each as the person form would, or update the person the
     * line names; nothing is imported when any line is refused.
     */
    @PostMapping("/import")
    public ImportView importPeople(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid ImportForm form) {
        ImportService.Imported imported = imports.importPeople(sheetId, SignedIn.name(user), form.text());
        return new ImportView(imported.added().stream().map(this::view).toList(),
                imported.updated().stream().map(this::view).toList());
    }

    /** Change a person's name and record their grade from its date, from the version of the person the form loaded. */
    @PutMapping("/{personId}")
    public PersonView edit(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long personId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid PersonForm form) {
        if (form.version() == null) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The version of the person edited is required.");
        }
        return view(service.edit(sheetId, SignedIn.name(user), personId, form.version(), form.name(),
                form.grade(), form.gradeFrom(), form.terms(), form.termsFrom(), form.contact(), form.termsGiven(),
                form.contactGiven(), form.tags(), form.gradeGiven()));
    }

    /** Give the selected people a grade from a date together, each as the person form would: the people changed. */
    @PostMapping("/grade")
    public List<PersonView> grade(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid BulkGradeForm form) {
        return bulkGrade.grade(sheetId, SignedIn.name(user), form.personIds(), form.grade(), form.from()).stream()
                .map(PersonView::of).toList();
    }

    /** Record the grade chosen on the person's row from the sheet's today, as the person form would. */
    @PostMapping("/{personId}/grade")
    public PersonView gradeRow(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long personId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
