52:    @Transactional(readOnly = true)
53:    public List<String> tree(String id) {
54:        List<String> ancestors = sheets.ancestors(id);
55:        String root = ancestors.isEmpty() ? id : ancestors.get(ancestors.size() - 1);
56:        List<String> tree = new ArrayList<>(List.of(root));
57:        tree.addAll(sheets.descendants(root));
