72:        Sheet sheet = load(id);
73:        Rollups.Rollup before = rollups.take(id);
74:        if (!today.equals(sheet.getToday())) {
75:            LocalDate leaving = sheet.getToday();
76:            before.people().forEach((personId, figures) -> {
77:                people.findById(personId).ifPresent(person -> person.snapshot(leaving, figures.dueTotal()));
78:                audit.recordOnCommit("SNAPSHOT sheet=" + id + " by=" + user
79:                        + " name=" + figures.name() + " due-total=" + Rollups.shown(figures.dueTotal()));
80:            });
81:            events.publishEvent(new TodayLeaving(id, sheet.getToday()));
82:        }
